{
  "triples": [
    {
      "subject": "NwQM",
      "predicate": "uses",
      "object": "information from multiple sources",
      "object_type": "Other",
      "source_sentence": "In this paper we propose Neural wikipedia Quality Monitor (NwQM) which integrates information from multiple sources, i.e., main page text, metadata and html rendering resulting in improved quality assessment."
    },
    {
      "subject": "BERT",
      "predicate": "uses",
      "object": "document representation",
      "object_type": "Other",
      "source_sentence": "However, contrary to document representation using BERT , which is not adequate for large text documents, we first segment articles organically based on sections."
    }
  ]
}

{
  "triples": [
    {
      "subject": "XML",
      "predicate": "uses",
      "object": "mediawiki xml parser",
      "object_type": "Method",
      "source_sentence": "We parsed each file using mediawiki xml parser10 and in one linear scan we tried to locate if the main page text and talk page text is in the same dump xml file."
    },
    {
      "subject": "Wikipedia Article",
      "predicate": "uses",
      "object": "dictionary",
      "object_type": "Other",
      "source_sentence": "More specifically if we encounter the main Wikipedia article Cleopatra, we remember it in a dictionary and seek to locate Talk:Cleopatra in future scans or vice versa."
    }
  ]
}

{
  "triples": [
    {
      "subject": "Features",
      "predicate": "uses",
      "object": "mediawiki parser",
      "object_type": "Other",
      "source_sentence": "replace the meta content in the page such as infobox, level 1 section headings, level 2 section heading, internal wikilink, exter- nal link, inline reference, footnote template, image template, quotation template and categories into special tokens which act as additional features us- ing mediawiki parser14."
    },
    {
      "subject": "Models",
      "predicate": "uses",
      "object": "pre-processed text",
      "object_type": "Other",
      "source_sentence": "We use this pre-processed text in the subsequent models."
    }
  ]
}

{
  "triples": [
    {
      "subject": "BERT model",
      "predicate": "trainedOn",
      "object": "Wikipedia pages",
      "object_type": "Dataset",
      "source_sentence": "We fine tune the BERT model on the extracted Wikipedia pages for classifying them into the 6 quality categories."
    },
    {
      "subject": "BERT model",
      "predicate": "uses",
      "object": "Softmax",
      "object_type": "Method",
      "source_sentence": "We pass the pre- processed textual content of the Wikipedia page to the BERT model and pass the [CLS] token's repre- sentation to a dense followed by softmax layers to classify the page."
    }
  ]
}

{
  "triples": [
    {
      "subject": "Sentence",
      "predicate": "uses",
      "object": "GRU",
      "object_type": "Other",
      "source_sentence": "pass each sentence through the Google Universe → GRU"
    },
    {
      "subject": "embeddings",
      "predicate": "uses",
      "object": "Global Average Pooling",
      "object_type": "Other",
      "source_sentence": "These sentence embeddings are then passed through a global average pooling layer"
    },
    {
      "subject": "Input",
      "predicate": "uses",
      "object": "screenshot of the wikipage",
      "object_type": "Other",
      "source_sentence": "The input to the fine tuned Inception model is the screenshot of the wikipage"
    },
    {
      "subject": "Text",
      "predicate": "uses",
      "object": "Information",
      "object_type": "Other",
      "source_sentence": "We integrate this information with the text and talk content of the page"
    },
    {
      "subject": "Sentence Embeddings",
      "predicate": "produces",
      "object": "512 dimensional representation of the sentence",
      "object_type": "Other",
      "source_sentence": "Sentence Encoder model to obtain a 512 dimensional representation of the sentence"
    },
    {
      "subject": "Global Average Pooling",
      "predicate": "produces",
      "object": "200 dimensional final representation",
      "object_type": "Other",
      "source_sentence": "These sentence embeddings are then passed through a global average pooling layer followed by a dense layer to get a 200 dimensional final representation of the talk page"
    }
  ]
}

{
  "triples": [
    {
      "subject": "BERT",
      "predicate": "uses",
      "object": "pre-trained weights",
      "object_type": "Other",
      "source_sentence": "We load the pre-trained weights of BERT-base model from TensorflowHub15."
    },
    {
      "subject": "Universal Sentence Encoder",
      "predicate": "uses",
      "object": "implementation",
      "object_type": "Other",
      "source_sentence": "We use the implementation of Google Universal Sentence Encoder available at TensorFlow Hub16."
    },
    {
      "subject": "training",
      "predicate": "uses",
      "object": "Adam optimizer",
      "object_type": "Other",
      "source_sentence": "We train the hierarchical content encoder for 10 epochs with a learning rate of 0.001 and batches of 16 using Adam optimizer."
    },
    {
      "subject": "fine-tuning",
      "predicate": "uses",
      "object": "Adam optimizer",
      "object_type": "Other",
      "source_sentence": "For fine tuning the BERT models, we use the Adam optimizer with a learning rate of 2e-5."
    },
    {
      "subject": "fine-tuning",
      "predicate": "uses",
      "object": "Adam optimizer",
      "object_type": "Other",
      "source_sentence": "To fine tune the Inception V3 model, we again use Adam optimizer with a learning rate 1e-4 and train for 20 epochs."
    },
    {
      "subject": "training",
      "predicate": "uses",
      "object": "categorical cross-entropy",
      "object_type": "Other",
      "source_sentence": "We employ the categorical cross-entropy as loss function for all the models and train using batches of size 16."
    },
    {
      "subject": "dropout",
      "predicate": "uses",
      "object": "probability",
      "object_type": "Other",
      "source_sentence": "We further utilize dropout probability of 0.5 in the dense layers."
    }
  ]
}

{
  "triples": [
    {
      "subject": "NwQM",
      "predicate": "uses",
      "object": "confusion matrix",
      "object_type": "Other",
      "source_sentence": "Confusion matrix: We first tabulate the confusion matrix obtained by NwQM on test data in Figure 2."
    },
    {
      "subject": "NwQM",
      "predicate": "uses",
      "object": "class specific features",
      "object_type": "Other",
      "source_sentence": "NwQM can capture class specific features significantly better thus showing lower mistakes for certain datapoints especially in case of Start, B and C classes."
    }
  ]
}

{
  "triples": [
    {
      "subject": "BERT",
      "predicate": "addresses",
      "object": "classification",
      "object_type": "Task",
      "source_sentence": "Deep learning models such as BERT have often been shown to rely on surface forms as shotcuts for classification instead of semantic understanding."
    },
    {
      "subject": "NwQM",
      "predicate": "addresses",
      "object": "classification",
      "object_type": "Task",
      "source_sentence": "We investigate whether NwQM is relying spurious signals like article length in final classification."
    }
  ]
}
